from httpbin.core import app
client = app.test_client()
allowed = {200, 500}
for _ in range(30):
    r = client.get('/status/200,500')
    assert r.status_code in allowed, f'Got unexpected {r.status_code}'

from httpbin.core import app
client = app.test_client()
allowed = {200, 404}
for _ in range(20):
    r = client.get('/status/200:9,404:1')
    assert r.status_code in allowed, f'Got unexpected {r.status_code}'
